<?php

/**
 * Script para decodificar blobs WACOM-STU430 reales (formato BD)
 * Extrae metadatos y nota que la firma está encriptada por el Wacom
 */

$PREFIJO = 'WACOM-STU430-';

// ============================================
// PEGA AQUÍ TUS BLOBS (uno por línea en el array)
// ============================================
$BLOBS_TO_TEST = [
    // Blob 1: ID 25
    'WACOM-STU430-',
    
    // Blob 2: ID 24
    'WACOM-STU430-
',
    
    // Blob 3: Formato simulado (referencia - funciona)
    'WACOM-STU430-',
];

// ============================================
// FUNCIONES
// ============================================
function decodificarEstructuraWacomReal(string $blob): ?array
{
    global $PREFIJO;
    
    if (!str_starts_with($blob, $PREFIJO)) {
        return null;
    }
    
    $json = base64_decode(substr($blob, strlen($PREFIJO)), true);
    if ($json === false) {
        return null;
    }
    
    $estructura = json_decode($json, true);
    if (!is_array($estructura)) {
        return null;
    }
    
    if (!isset($estructura['nombre'], $estructura['dni'], 
        $estructura['firma_encriptada_wacom'], $estructura['fecha'])) {
        return null;
    }
    
    return $estructura;
}

function analizarFirmaEncriptada(string $firmaEncriptada): array
{
    global $PREFIJO;
    
    $resultado = [
        'es_formato_simulado' => false,
        'es_binario_wacom_real' => false,
        'tamano_bytes' => 0,
        'puede_extraer_png' => false,
        'detalle' => ''
    ];
    
    if (str_starts_with($firmaEncriptada, $PREFIJO)) {
        $contenido = substr($firmaEncriptada, strlen($PREFIJO));
        $decoded = base64_decode($contenido, true);
        
        if ($decoded !== false) {
            $resultado['tamano_bytes'] = strlen($decoded);
            
            // Verificar si es JSON (formato simulado)
            $jsonTest = json_decode($decoded, true);
            if (is_array($jsonTest) && isset($jsonTest['firma_base64'])) {
                $resultado['es_formato_simulado'] = true;
                $resultado['puede_extraer_png'] = true;
                $resultado['detalle'] = 'Formato simulado (JSON anidado con firma_base64)';
                return $resultado;
            }
            
            // Verificar magic bytes PNG
            if (substr($decoded, 0, 8) === "\x89PNG\r\n\x1a\n") {
                $resultado['es_binario_wacom_real'] = true;
                $resultado['puede_extraer_png'] = true;
                $resultado['detalle'] = 'PNG directo sin encriptar (poco probable en Wacom real)';
                return $resultado;
            }
            
            // Es binario encriptado real del Wacom
            $resultado['es_binario_wacom_real'] = true;
            $resultado['puede_extraer_png'] = false;
            $resultado['detalle'] = 'Datos binarios encriptados por Wacom STU-430 (requiere SDK Wacom para descifrar)';
            return $resultado;
        }
    }
    
    $resultado['detalle'] = 'Formato no reconocido';
    return $resultado;
}

// ============================================
// EJECUCIÓN
// ============================================
echo "=== ANÁLISIS DE BLOBS WACOM-STU430 (FORMATO REAL BD) ===\n\n";

$exitosos = 0;
$fallidos = 0;

foreach ($BLOBS_TO_TEST as $index => $blob) {
    $num = $index + 1;
    echo "--- Blob #{$num} ---\n";
    
    $estructura = decodificarEstructuraWacomReal($blob);
    if ($estructura) {
        $exitosos++;
        echo "✅ ESTRUCTURA EXTERNA DECODIFICADA CORRECTAMENTE\n";
        echo "   👤 Nombre: {$estructura['nombre']}\n";
        echo "   🆔 DNI: {$estructura['dni']}\n";
        echo "   📅 Fecha: {$estructura['fecha']}\n";
        echo "   🔧 Serial: " . ($estructura['serial_pad'] ?? 'N/A') . "\n";
        
        // Analizar firma encriptada
        $analisis = analizarFirmaEncriptada($estructura['firma_encriptada_wacom']);
        echo "   🔐 Firma encriptada:\n";
        echo "      - Tamaño: {$analisis['tamano_bytes']} bytes\n";
        echo "      - Formato simulado: " . ($analisis['es_formato_simulado'] ? 'SÍ' : 'NO') . "\n";
        echo "      - Binario Wacom real: " . ($analisis['es_binario_wacom_real'] ? 'SÍ' : 'NO') . "\n";
        echo "      - ¿Se puede extraer PNG?: " . ($analisis['puede_extraer_png'] ? 'SÍ' : 'NO') . "\n";
        echo "      - Detalle: {$analisis['detalle']}\n";
        
        if ($analisis['es_formato_simulado'] && $analisis['puede_extraer_png']) {
            // Extraer PNG del formato simulado
            $firmaEnc = $estructura['firma_encriptada_wacom'];
            $contenido = substr($firmaEnc, strlen($PREFIJO));
            $jsonPaquete = base64_decode($contenido, true);
            $paquete = json_decode($jsonPaquete, true);
            $pngBase64 = $paquete['firma_base64'] ?? null;
            
            if ($pngBase64) {
                $imagen = base64_decode($pngBase64, true);
                $filename = "firma_blob_{$num}_simulada_" . date('His') . ".png";
                file_put_contents($filename, $imagen);
                echo "      💾 PNG extraído y guardado: {$filename}\n";
            }
        } elseif ($analisis['es_binario_wacom_real']) {
            // Guardar datos binarios encriptados para análisis posterior
            $firmaEnc = $estructura['firma_encriptada_wacom'];
            $contenido = substr($firmaEnc, strlen($PREFIJO));
            $binario = base64_decode($contenido, true);
            $filename = "firma_blob_{$num}_wacom_encriptada_" . date('His') . ".bin";
            file_put_contents($filename, $binario);
            echo "      💾 Datos encriptados guardados: {$filename} (para análisis con SDK Wacom)\n";
        }
        
    } else {
        $fallidos++;
        echo "❌ FALLÓ - Estructura externa no válida\n";
    }
    echo "\n";
}

echo "=== RESUMEN ===\n";
echo "Decodificados correctamente: {$exitosos}\n";
echo "Fallidos: {$fallidos}\n";
echo "Total: " . count($BLOBS_TO_TEST) . "\n\n";

echo "=== NOTA IMPORTANTE ===\n";
echo "Los blobs #1 y #2 son FIRMAS REALES del Wacom STU-430.\n";
echo "El campo 'firma_encriptada_wacom' contiene datos BINARIOS ENCRIPTADOS\n";
echo "por el dispositivo Wacom (AES-256/RSA). NO es JSON anidado.\n\n";
echo "Para extraer la imagen PNG necesitas:\n";
echo "1. Usar el SDK oficial de Wacom (Signature SDK)\n";
echo "2. Tener la clave privada correspondiente\n";
echo "3. Llamar a la función de descifrado del SDK\n\n";
echo "El blob #3 es el formato SIMULADO que genera el frontend actual.\n";
echo "Ese SÍ permite extraer PNG directamente.\n";